#!/usr/bin/env node

import { mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const registry = JSON.parse(readFileSync(resolve(repo, 'resources/spec/rules.json'), 'utf8'))
const outputDir = resolve(repo, 'docs/rules')

const frontmatter = (title, description) => `---
title: ${JSON.stringify(title)}
description: ${JSON.stringify(description)}
---

<!-- Generated by scripts/spec-rule-index.mjs. Do not edit directly. -->

`

const scopePage = (scope) => {
  const rules = registry.rules.filter((rule) => rule.scope === scope.id)
  const rows = rules.map((rule) =>
    `| \`${rule.id}\` | ${rule.part} | ${rule.title.replaceAll('|', '\\|')} |`,
  )
  return frontmatter(`${scope.title} rules`, scope.description) +
    `# ${scope.title} rules\n\n${scope.description}\n\n` +
    `This focused view contains ${rules.length} of ${registry.rules.length} active normative rules. ` +
    'It is navigation, not a conformance profile: rules in the other views remain mandatory where applicable. ' +
    'Rule IDs remain stable when titles are clarified or rules move between views.\n\n' +
    'Return to the [rule index](./) or read the complete [formal grammar](../grammar).\n\n' +
    '| Rule | Part | Clause |\n|---|---:|---|\n' + rows.join('\n') + '\n'
}

const indexPage = () => {
  const rows = registry.scopes.map((scope) => {
    const count = registry.rules.filter((rule) => rule.scope === scope.id).length
    const title = scope.title.replaceAll('|', '\\|')
    const description = scope.description.replaceAll('|', '\\|')
    return `| [${title}](./${scope.id}) | ${count} | ${description} |`
  })
  const retired = registry.retired.map((rule) =>
    `| \`${rule.id}\` | ${rule.title.replaceAll('|', '\\|')} | \`${rule.replacement}\` |`,
  )
  return frontmatter(
    'Normative rule index',
    'Focused views of every active Carve rule, grouped by implementation responsibility.',
  ) + '# Normative rule index\n\n' +
    'Carve has one normative language contract. These views filter that contract by ' +
    'implementation responsibility; they do not define conformance profiles or make any rule optional.\n\n' +
    '| View | Rules | Responsibility |\n|---|---:|---|\n' + rows.join('\n') + '\n\n' +
    `Together the views cover all ${registry.rules.length} active rules exactly once. ` +
    'The source metadata lives in `resources/spec/rules.json`.\n\n' +
    '## Retired rule IDs\n\n' +
    'Retired IDs are never reused. Their replacement points to the document that now owns the contract.\n\n' +
    '| Rule | Last title | Replacement |\n|---|---|---|\n' + retired.join('\n') + '\n'
}

const outputs = new Map([
  ['index.md', indexPage()],
  ...registry.scopes.map((scope) => [`${scope.id}.md`, scopePage(scope)]),
])

const indexedCount = registry.scopes.reduce((count, scope) =>
  count + registry.rules.filter((rule) => rule.scope === scope.id).length, 0)
if (indexedCount !== registry.rules.length) {
  throw new Error(`focused views cover ${indexedCount} of ${registry.rules.length} active rules`)
}
for (const scope of registry.scopes) {
  if (!registry.rules.some((rule) => rule.scope === scope.id)) {
    throw new Error(`focused view '${scope.id}' contains no active rules`)
  }
}

const command = process.argv[2] ?? '--check'
if (command === '--write') {
  mkdirSync(outputDir, { recursive: true })
  for (const [file, content] of outputs) writeFileSync(resolve(outputDir, file), content)
  console.log(`wrote ${outputs.size} focused rule-index pages for ${registry.rules.length} rules`)
} else if (command === '--check') {
  const stale = []
  for (const [file, expected] of outputs) {
    let actual
    try {
      actual = readFileSync(resolve(outputDir, file), 'utf8')
    } catch {
      actual = undefined
    }
    if (actual !== expected) stale.push(file)
  }
  let unexpected = []
  try {
    unexpected = readdirSync(outputDir)
      .filter((file) => file.endsWith('.md') && !outputs.has(file))
  } catch {
    // Missing outputDir is already represented by every expected file above.
  }
  if (stale.length) {
    console.error(`stale focused rule-index page(s): ${stale.join(', ')}; run: npm run spec:rules:write`)
    process.exitCode = 1
  }
  if (unexpected.length) {
    console.error(`unexpected focused rule-index page(s): ${unexpected.join(', ')}; delete them`)
    process.exitCode = 1
  }
  if (!process.exitCode) {
    console.log(`${outputs.size} focused rule-index pages cover ${registry.rules.length} rules`)
  }
} else {
  console.error(`unknown command: ${command}`)
  process.exitCode = 2
}
